// Helper to build IR from code
func buildIR(code string) (*ast.Program, *ir.Module, error) {
	lex := lexer.New(code)
	tokens, err := lex.Tokenize()
	if err != nil {
		return nil, nil, err
	}

	p := parser.New(tokens)
	program, err := p.Parse()
	if err != nil {
		return nil, nil, err
	}

	analyzer := sema.NewAnalyzer()
	_, err = analyzer.Analyze(program)
	if err != nil {
		return nil, nil, err
	}

	builder := ir.NewBuilder()
	mod, err := builder.Build(program)
	if err != nil {
		return nil, nil, err
	}

	return program, mod, nil
}

package optimizer

import (
	"jcc/internal/ir"
)

// Optimizer performs IR optimizations
type Optimizer struct {
	module *ir.Module
}

// NewOptimizer creates a new optimizer
func NewOptimizer(module *ir.Module) *Optimizer {
	return &Optimizer{
		module: module,
	}
}

// Optimize runs all optimization passes
func (opt *Optimizer) Optimize() error {
	// Run passes in order
	opt.constantFold()
	opt.deadCodeElimination()
	opt.commonSubexpressionElimination()
	return nil
}

// constantFold performs constant folding optimization
func (opt *Optimizer) constantFold() {
	for _, fn := range opt.module.Functions {
		for _, block := range fn.Blocks {
			opt.foldBlockConstants(block)
		}
	}
}

// foldBlockConstants folds constants in a block
func (opt *Optimizer) foldBlockConstants(block *ir.BasicBlock) {
	newInsts := []*ir.Instruction{}

	for i, inst := range block.Insts {
		if inst.Type == ir.InstBinOp && len(inst.Ops) >= 2 {
			left := inst.Ops[0]
			right := inst.Ops[1]

			// Check if both operands are literals
			leftLit := opt.findLiteralValue(block.Insts[:i], left.ID)
			rightLit := opt.findLiteralValue(block.Insts[:i], right.ID)

			if leftLit != nil && rightLit != nil {
				result := opt.evalBinOp(inst.OpType, leftLit, rightLit)
				if result != nil {
					// Replace with constant
					inst.Type = ir.InstLiteral
					inst.Meta = result
					inst.Ops = []ir.Value{}
				}
			}
		}
		newInsts = append(newInsts, inst)
	}

	block.Insts = newInsts
}

// findLiteralValue finds a literal value by ID in instruction list
func (opt *Optimizer) findLiteralValue(insts []*ir.Instruction, valID uint32) interface{} {
	for _, inst := range insts {
		if inst.Type == ir.InstLiteral && inst.Result.ID == valID {
			return inst.Meta
		}
	}
	return nil
}

// evalBinOp evaluates a binary operation on constants
func (opt *Optimizer) evalBinOp(op string, left, right interface{}) interface{} {
	leftInt, leftOK := toInt64(left)
	rightInt, rightOK := toInt64(right)

	if leftOK && rightOK {
		switch op {
		case "add":
			return leftInt + rightInt
		case "sub":
			return leftInt - rightInt
		case "mul":
			return leftInt * rightInt
		case "div":
			if rightInt != 0 {
				return leftInt / rightInt
			}
		case "mod":
			if rightInt != 0 {
				return leftInt % rightInt
			}
		case "eq":
			return leftInt == rightInt
		case "ne":
			return leftInt != rightInt
		case "lt":
			return leftInt < rightInt
		case "le":
			return leftInt <= rightInt
		case "gt":
			return leftInt > rightInt
		case "ge":
			return leftInt >= rightInt
		}
	}

	// Float operations
	leftFloat, leftFOK := toFloat64(left)
	rightFloat, rightFOK := toFloat64(right)

	if leftFOK && rightFOK {
		switch op {
		case "add":
			return leftFloat + rightFloat
		case "sub":
			return leftFloat - rightFloat
		case "mul":
			return leftFloat * rightFloat
		case "div":
			if rightFloat != 0 {
				return leftFloat / rightFloat
			}
		case "eq":
			return leftFloat == rightFloat
		case "ne":
			return leftFloat != rightFloat
		case "lt":
			return leftFloat < rightFloat
		case "le":
			return leftFloat <= rightFloat
		case "gt":
			return leftFloat > rightFloat
		case "ge":
			return leftFloat >= rightFloat
		}
	}

	return nil
}

// deadCodeElimination removes dead instructions
func (opt *Optimizer) deadCodeElimination() {
	for _, fn := range opt.module.Functions {
		for _, block := range fn.Blocks {
			opt.eliminateDeadCode(block)
		}
	}
}

// eliminateDeadCode removes unreachable instructions
func (opt *Optimizer) eliminateDeadCode(block *ir.BasicBlock) {
	// Remove code after unconditional returns/branches
	for i, inst := range block.Insts {
		if inst.Type == ir.InstReturn || inst.Type == ir.InstBranch {
			block.Insts = block.Insts[:i+1]
			break
		}
	}
}

// commonSubexpressionElimination (CSE) - simplified version
func (opt *Optimizer) commonSubexpressionElimination() {
	for _, fn := range opt.module.Functions {
		for _, block := range fn.Blocks {
			opt.eliminateCSE(block)
		}
	}
}

// eliminateCSE eliminates common subexpressions in a block
func (opt *Optimizer) eliminateCSE(block *ir.BasicBlock) {
	// Track identical expressions
	exprMap := make(map[string]uint32)

	newInsts := []*ir.Instruction{}
	for _, inst := range block.Insts {
		if inst.Type == ir.InstBinOp {
			// Create expression signature
			sig := opt.createExprSignature(inst)
			if prevID, exists := exprMap[sig]; exists {
				// Replace with previous result
				inst.Type = ir.InstLoad
				inst.Ops = []ir.Value{{ID: prevID}}
				inst.OpType = ""
			} else {
				exprMap[sig] = inst.Result.ID
			}
		}
		newInsts = append(newInsts, inst)
	}

	block.Insts = newInsts
}

// createExprSignature creates a signature for an expression
func (opt *Optimizer) createExprSignature(inst *ir.Instruction) string {
	if inst.Type == ir.InstBinOp && len(inst.Ops) >= 2 {
		// Simple signature: "op-op1-op2"
		return inst.OpType + "-" + string(rune(inst.Ops[0].ID)) + "-" + string(rune(inst.Ops[1].ID))
	}
	return ""
}

// Utility functions

func toInt64(v interface{}) (int64, bool) {
	if i, ok := v.(int64); ok {
		return i, true
	}
	return 0, false
}

func toFloat64(v interface{}) (float64, bool) {
	if f, ok := v.(float64); ok {
		return f, true
	}
	if i, ok := v.(int64); ok {
		return float64(i), true
	}
	return 0, false
}

package optimizer

import (
	"jcc/internal/ast"
	"jcc/internal/ir"
	"jcc/internal/lexer"
	"jcc/internal/parser"
	"jcc/internal/sema"
	"testing"
)

func TestConstantFolding(t *testing.T) {
	code := `
	function test()
		5 + 3
	end
	`
	prog, mod, err := buildOptimizeIR(code)
	if err != nil {
		t.Fatalf("build error: %v", err)
	}

	// After constant folding, 5 + 3 should become literal 8
	fn := mod.Functions[0]
	found := false
	for _, inst := range fn.Blocks[0].Insts {
		if inst.Type == ir.InstLiteral {
			if val, ok := inst.Meta.(int64); ok && val == 8 {
				found = true
			}
		}
	}
	if !found {
		t.Error("constant folding did not produce expected result")
	}
}

func TestDeadCodeElimination(t *testing.T) {
	code := `
	function test()
		return 42
		100
	end
	`
	prog, mod, err := buildOptimizeIR(code)
	if err != nil {
		t.Fatalf("build error: %v", err)
	}

	// Code after return should be removed
	fn := mod.Functions[0]
	instAfterReturn := false
	foundReturn := false

	for _, inst := range fn.Blocks[0].Insts {
		if inst.Type == ir.InstReturn {
			foundReturn = true
		} else if foundReturn && inst.Type != ir.InstNop {
			instAfterReturn = true
		}
	}

	if instAfterReturn {
		t.Error("dead code after return was not eliminated")
	}
}

func TestOptimizerCreation(t *testing.T) {
	mod := ir.NewModule()
	opt := NewOptimizer(mod)
	if opt == nil {
		t.Fatal("optimizer is nil")
	}
}

func TestOptimizePass(t *testing.T) {
	code := `
	function test()
		42 + 8
	end
	`
	prog, mod, err := buildOptimizeIR(code)
	if err != nil {
		t.Fatalf("build error: %v", err)
	}

	if len(mod.Functions) != 1 {
		t.Fatal("expected 1 function")
	}
}

// Helper to build and optimize IR
func buildOptimizeIR(code string) (*ast.Program, *ir.Module, error) {
	lex := lexer.New(code)
	tokens, err := lex.Tokenize()
	if err != nil {
		return nil, nil, err
	}

	p := parser.New(tokens)
	program, err := p.Parse()
	if err != nil {
		return nil, nil, err
	}

	analyzer := sema.NewAnalyzer()
	_, err = analyzer.Analyze(program)
	if err != nil {
		return nil, nil, err
	}

	builder := ir.NewBuilder()
	mod, err := builder.Build(program)
	if err != nil {
		return nil, nil, err
	}

	opt := NewOptimizer(mod)
	err = opt.Optimize()
	if err != nil {
		return nil, nil, err
	}

	return program, mod, nil
}

package codegen

import (
	"fmt"
	"jcc/internal/ir"
)

// BytecodeOp represents a bytecode operation
type BytecodeOp uint8

const (
	OpPush BytecodeOp = iota
	OpAdd
	OpSub
	OpMul
	OpDiv
	OpMod
	OpEq
	OpNe
	OpLt
	OpLe
	OpGt
	OpGe
	OpAnd
	OpOr
	OpNot
	OpNeg
	OpCall
	OpRet
	OpLoad
	OpStore
	OpBranch
	OpCondBranch
	OpLabel
	OpHalt
)

// Bytecode represents compiled bytecode
type Bytecode struct {
	Code      []uint8
	Constants []interface{}
	Labels    map[string]int
}

// Codegen compiles IR to bytecode
type Codegen struct {
	module    *ir.Module
	bytecode  *Bytecode
	nextConst int
	labelMap  map[string]int
}

// NewCodegen creates a new code generator
func NewCodegen(module *ir.Module) *Codegen {
	return &Codegen{
		module:   module,
		bytecode: &Bytecode{Code: []uint8{}, Constants: []interface{}{}, Labels: make(map[string]int)},
		labelMap: make(map[string]int),
	}
}

// Generate compiles IR to bytecode
func (cg *Codegen) Generate() (*Bytecode, error) {
	for _, fn := range cg.module.Functions {
		if err := cg.compileFunction(fn); err != nil {
			return nil, err
		}
	}

	// Add halt instruction at the end
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(OpHalt))

	return cg.bytecode, nil
}

// compileFunction compiles a function to bytecode
func (cg *Codegen) compileFunction(fn *ir.Function) error {
	// Mark function entry
	fnLabel := fmt.Sprintf("fn_%s", fn.Name)
	cg.labelMap[fnLabel] = len(cg.bytecode.Code)

	for _, block := range fn.Blocks {
		if err := cg.compileBlock(block); err != nil {
			return err
		}
	}

	return nil
}

// compileBlock compiles a basic block to bytecode
func (cg *Codegen) compileBlock(block *ir.BasicBlock) error {
	blockLabel := fmt.Sprintf("block_%s", block.Name)
	cg.labelMap[blockLabel] = len(cg.bytecode.Code)

	for _, inst := range block.Insts {
		if err := cg.compileInstruction(inst); err != nil {
			return err
		}
	}

	return nil
}

// compileInstruction compiles a single instruction
func (cg *Codegen) compileInstruction(inst *ir.Instruction) error {
	switch inst.Type {
	case ir.InstLiteral:
		return cg.compileLiteral(inst)
	case ir.InstBinOp:
		return cg.compileBinOp(inst)
	case ir.InstUnaryOp:
		return cg.compileUnaryOp(inst)
	case ir.InstCall:
		return cg.compileCall(inst)
	case ir.InstReturn:
		return cg.compileReturn(inst)
	case ir.InstLoad:
		return cg.compileLoad(inst)
	case ir.InstStore:
		return cg.compileStore(inst)
	case ir.InstBranch:
		return cg.compileBranch(inst)
	case ir.InstCondBranch:
		return cg.compileCondBranch(inst)
	case ir.InstLabel:
		cg.labelMap[fmt.Sprintf("%v", inst.Meta)] = len(cg.bytecode.Code)
		return nil
	default:
		return nil
	}
}

// compileLiteral compiles a literal value
func (cg *Codegen) compileLiteral(inst *ir.Instruction) error {
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(OpPush))
	constIdx := cg.addConstant(inst.Meta)
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(constIdx))
	return nil
}

// compileBinOp compiles a binary operation
func (cg *Codegen) compileBinOp(inst *ir.Instruction) error {
	op, ok := opToBytecodeOp(inst.OpType)
	if !ok {
		return fmt.Errorf("unknown binary operator: %s", inst.OpType)
	}

	cg.bytecode.Code = append(cg.bytecode.Code, uint8(op))
	return nil
}

// compileUnaryOp compiles a unary operation
func (cg *Codegen) compileUnaryOp(inst *ir.Instruction) error {
	var op BytecodeOp
	switch inst.OpType {
	case "not":
		op = OpNot
	case "-":
		op = OpNeg
	default:
		op = OpNeg
	}

	cg.bytecode.Code = append(cg.bytecode.Code, uint8(op))
	return nil
}

// compileCall compiles a function call
func (cg *Codegen) compileCall(inst *ir.Instruction) error {
	fnName, ok := inst.Meta.(string)
	if !ok {
		return fmt.Errorf("invalid function name in call")
	}

	// For built-in functions, use special handling
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(OpCall))
	constIdx := cg.addConstant(fnName)
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(constIdx))
	return nil
}

// compileReturn compiles a return instruction
func (cg *Codegen) compileReturn(inst *ir.Instruction) error {
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(OpRet))
	return nil
}

// compileLoad compiles a load instruction
func (cg *Codegen) compileLoad(inst *ir.Instruction) error {
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(OpLoad))
	if len(inst.Ops) > 0 {
		// Store variable name as constant
		constIdx := cg.addConstant(inst.Ops[0].Name)
		cg.bytecode.Code = append(cg.bytecode.Code, uint8(constIdx))
	}
	return nil
}

// compileStore compiles a store instruction
func (cg *Codegen) compileStore(inst *ir.Instruction) error {
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(OpStore))
	if len(inst.Ops) > 0 {
		constIdx := cg.addConstant(inst.Ops[0].Name)
		cg.bytecode.Code = append(cg.bytecode.Code, uint8(constIdx))
	}
	return nil
}

// compileBranch compiles an unconditional branch
func (cg *Codegen) compileBranch(inst *ir.Instruction) error {
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(OpBranch))
	// Placeholder for label address (will be patched)
	cg.bytecode.Code = append(cg.bytecode.Code, 0)
	return nil
}

// compileCondBranch compiles a conditional branch
func (cg *Codegen) compileCondBranch(inst *ir.Instruction) error {
	cg.bytecode.Code = append(cg.bytecode.Code, uint8(OpCondBranch))
	// Placeholder for label addresses
	cg.bytecode.Code = append(cg.bytecode.Code, 0)
	return nil
}

// addConstant adds a constant to the constant pool
func (cg *Codegen) addConstant(val interface{}) int {
	idx := len(cg.bytecode.Constants)
	cg.bytecode.Constants = append(cg.bytecode.Constants, val)
	return idx
}

// opToBytecodeOp converts IR operator to bytecode operator
func opToBytecodeOp(op string) (BytecodeOp, bool) {
	switch op {
	case "add":
		return OpAdd, true
	case "sub":
		return OpSub, true
	case "mul":
		return OpMul, true
	case "div":
		return OpDiv, true
	case "mod":
		return OpMod, true
	case "eq":
		return OpEq, true
	case "ne":
		return OpNe, true
	case "lt":
		return OpLt, true
	case "le":
		return OpLe, true
	case "gt":
		return OpGt, true
	case "ge":
		return OpGe, true
	case "and":
		return OpAnd, true
	case "or":
		return OpOr, true
	default:
		return 0, false
	}
}

// GetBytecode returns the generated bytecode
func (cg *Codegen) GetBytecode() *Bytecode {
	return cg.bytecode
}

package codegen

import (
	"fmt"
)

// VM is a simple stack-based virtual machine
type VM struct {
	bytecode  *Bytecode
	stack     []interface{}
	variables map[string]interface{}
	pc        int // Program counter
}

// NewVM creates a new virtual machine
func NewVM(bytecode *Bytecode) *VM {
	return &VM{
		bytecode:  bytecode,
		stack:     []interface{}{},
		variables: make(map[string]interface{}),
		pc:        0,
	}
}

// Run executes the bytecode
func (vm *VM) Run() (interface{}, error) {
	for vm.pc < len(vm.bytecode.Code) {
		opByte := vm.bytecode.Code[vm.pc]
		op := BytecodeOp(opByte)

		switch op {
		case OpPush:
			if err := vm.executePush(); err != nil {
				return nil, err
			}
		case OpAdd:
			if err := vm.executeBinOp(OpAdd); err != nil {
				return nil, err
			}
		case OpSub:
			if err := vm.executeBinOp(OpSub); err != nil {
				return nil, err
			}
		case OpMul:
			if err := vm.executeBinOp(OpMul); err != nil {
				return nil, err
			}
		case OpDiv:
			if err := vm.executeBinOp(OpDiv); err != nil {
				return nil, err
			}
		case OpMod:
			if err := vm.executeBinOp(OpMod); err != nil {
				return nil, err
			}
		case OpEq:
			if err := vm.executeBinOp(OpEq); err != nil {
				return nil, err
			}
		case OpNe:
			if err := vm.executeBinOp(OpNe); err != nil {
				return nil, err
			}
		case OpLt:
			if err := vm.executeBinOp(OpLt); err != nil {
				return nil, err
			}
		case OpLe:
			if err := vm.executeBinOp(OpLe); err != nil {
				return nil, err
			}
		case OpGt:
			if err := vm.executeBinOp(OpGt); err != nil {
				return nil, err
			}
		case OpGe:
			if err := vm.executeBinOp(OpGe); err != nil {
				return nil, err
			}
		case OpAnd:
			if err := vm.executeBinOp(OpAnd); err != nil {
				return nil, err
			}
		case OpOr:
			if err := vm.executeBinOp(OpOr); err != nil {
				return nil, err
			}
		case OpNot:
			if err := vm.executeNot(); err != nil {
				return nil, err
			}
		case OpNeg:
			if err := vm.executeNeg(); err != nil {
				return nil, err
			}
		case OpCall:
			if err := vm.executeCall(); err != nil {
				return nil, err
			}
		case OpRet:
			if len(vm.stack) > 0 {
				return vm.stack[len(vm.stack)-1], nil
			}
			return nil, nil
		case OpLoad:
			if err := vm.executeLoad(); err != nil {
				return nil, err
			}
		case OpStore:
			if err := vm.executeStore(); err != nil {
				return nil, err
			}
		case OpHalt:
			if len(vm.stack) > 0 {
				return vm.stack[len(vm.stack)-1], nil
			}
			return nil, nil
		default:
			return nil, fmt.Errorf("unknown opcode: %d", op)
		}

		vm.pc++
	}

	if len(vm.stack) > 0 {
		return vm.stack[len(vm.stack)-1], nil
	}
	return nil, nil
}

// executePush pushes a constant onto the stack
func (vm *VM) executePush() error {
	vm.pc++
	if vm.pc >= len(vm.bytecode.Code) {
		return fmt.Errorf("invalid push instruction")
	}

	constIdx := vm.bytecode.Code[vm.pc]
	if int(constIdx) >= len(vm.bytecode.Constants) {
		return fmt.Errorf("constant index out of bounds: %d", constIdx)
	}

	vm.stack = append(vm.stack, vm.bytecode.Constants[constIdx])
	return nil
}

// executeBinOp executes a binary operation
func (vm *VM) executeBinOp(op BytecodeOp) error {
	if len(vm.stack) < 2 {
		return fmt.Errorf("insufficient stack for binary op")
	}

	right := vm.stack[len(vm.stack)-1]
	left := vm.stack[len(vm.stack)-2]
	vm.stack = vm.stack[:len(vm.stack)-2]

	var result interface{}
	var err error

	switch op {
	case OpAdd:
		result, err = vm.add(left, right)
	case OpSub:
		result, err = vm.sub(left, right)
	case OpMul:
		result, err = vm.mul(left, right)
	case OpDiv:
		result, err = vm.div(left, right)
	case OpMod:
		result, err = vm.mod(left, right)
	case OpEq:
		result = vm.eq(left, right)
	case OpNe:
		result = !vm.eq(left, right).(bool)
	case OpLt:
		result, err = vm.lt(left, right)
	case OpLe:
		result, err = vm.le(left, right)
	case OpGt:
		result, err = vm.gt(left, right)
	case OpGe:
		result, err = vm.ge(left, right)
	case OpAnd:
		result = vm.toBool(left) && vm.toBool(right)
	case OpOr:
		result = vm.toBool(left) || vm.toBool(right)
	}

	if err != nil {
		return err
	}

	vm.stack = append(vm.stack, result)
	return nil
}

// executeNot executes logical NOT
func (vm *VM) executeNot() error {
	if len(vm.stack) < 1 {
		return fmt.Errorf("insufficient stack for not")
	}

	val := vm.stack[len(vm.stack)-1]
	vm.stack = vm.stack[:len(vm.stack)-1]
	vm.stack = append(vm.stack, !vm.toBool(val))
	return nil
}

// executeNeg executes negation
func (vm *VM) executeNeg() error {
	if len(vm.stack) < 1 {
		return fmt.Errorf("insufficient stack for negate")
	}

	val := vm.stack[len(vm.stack)-1]
	vm.stack = vm.stack[:len(vm.stack)-1]

	switch v := val.(type) {
	case int64:
		vm.stack = append(vm.stack, -v)
	case float64:
		vm.stack = append(vm.stack, -v)
	default:
		return fmt.Errorf("cannot negate %T", val)
	}

	return nil
}

// executeCall executes a function call
func (vm *VM) executeCall() error {
	vm.pc++
	if vm.pc >= len(vm.bytecode.Code) {
		return fmt.Errorf("invalid call instruction")
	}

	constIdx := vm.bytecode.Code[vm.pc]
	if int(constIdx) >= len(vm.bytecode.Constants) {
		return fmt.Errorf("constant index out of bounds")
	}

	fnName, ok := vm.bytecode.Constants[constIdx].(string)
	if !ok {
		return fmt.Errorf("function name is not string")
	}

	// Handle built-in functions
	return vm.callBuiltin(fnName)
}

// executeLoad executes a load instruction
func (vm *VM) executeLoad() error {
	vm.pc++
	if vm.pc >= len(vm.bytecode.Code) {
		return fmt.Errorf("invalid load instruction")
	}

	constIdx := vm.bytecode.Code[vm.pc]
	if int(constIdx) >= len(vm.bytecode.Constants) {
		return fmt.Errorf("constant index out of bounds")
	}

	varName, ok := vm.bytecode.Constants[constIdx].(string)
	if !ok {
		return fmt.Errorf("variable name is not string")
	}

	val, ok := vm.variables[varName]
	if !ok {
		return fmt.Errorf("undefined variable: %s", varName)
	}

	vm.stack = append(vm.stack, val)
	return nil
}

// executeStore executes a store instruction
func (vm *VM) executeStore() error {
	vm.pc++
	if vm.pc >= len(vm.bytecode.Code) {
		return fmt.Errorf("invalid store instruction")
	}

	constIdx := vm.bytecode.Code[vm.pc]
	if int(constIdx) >= len(vm.bytecode.Constants) {
		return fmt.Errorf("constant index out of bounds")
	}

	varName, ok := vm.bytecode.Constants[constIdx].(string)
	if !ok {
		return fmt.Errorf("variable name is not string")
	}

	if len(vm.stack) < 1 {
		return fmt.Errorf("insufficient stack for store")
	}

	val := vm.stack[len(vm.stack)-1]
	vm.variables[varName] = val
	return nil
}

// callBuiltin executes a built-in function
func (vm *VM) callBuiltin(fnName string) error {
	switch fnName {
	case "print":
		if len(vm.stack) < 1 {
			return fmt.Errorf("print requires 1 argument")
		}
		val := vm.stack[len(vm.stack)-1]
		fmt.Println(val)
		vm.stack = vm.stack[:len(vm.stack)-1]
		vm.stack = append(vm.stack, nil)
		return nil
	case "length":
		if len(vm.stack) < 1 {
			return fmt.Errorf("length requires 1 argument")
		}
		val := vm.stack[len(vm.stack)-1]
		vm.stack = vm.stack[:len(vm.stack)-1]

		switch v := val.(type) {
		case string:
			vm.stack = append(vm.stack, int64(len(v)))
		default:
			return fmt.Errorf("cannot get length of %T", val)
		}
		return nil
	default:
		return fmt.Errorf("unknown built-in function: %s", fnName)
	}
}

// Arithmetic operations

func (vm *VM) add(left, right interface{}) (interface{}, error) {
	switch l := left.(type) {
	case int64:
		switch r := right.(type) {
		case int64:
			return l + r, nil
		case float64:
			return float64(l) + r, nil
		}
	case float64:
		switch r := right.(type) {
		case int64:
			return l + float64(r), nil
		case float64:
			return l + r, nil
		}
	}
	return nil, fmt.Errorf("cannot add %T and %T", left, right)
}

func (vm *VM) sub(left, right interface{}) (interface{}, error) {
	switch l := left.(type) {
	case int64:
		switch r := right.(type) {
		case int64:
			return l - r, nil
		case float64:
			return float64(l) - r, nil
		}
	case float64:
		switch r := right.(type) {
		case int64:
			return l - float64(r), nil
		case float64:
			return l - r, nil
		}
	}
	return nil, fmt.Errorf("cannot subtract %T and %T", left, right)
}

func (vm *VM) mul(left, right interface{}) (interface{}, error) {
	switch l := left.(type) {
	case int64:
		switch r := right.(type) {
		case int64:
			return l * r, nil
		case float64:
			return float64(l) * r, nil
		}
	case float64:
		switch r := right.(type) {
		case int64:
			return l * float64(r), nil
		case float64:
			return l * r, nil
		}
	}
	return nil, fmt.Errorf("cannot multiply %T and %T", left, right)
}

func (vm *VM) div(left, right interface{}) (interface{}, error) {
	switch l := left.(type) {
	case int64:
		switch r := right.(type) {
		case int64:
			if r == 0 {
				return nil, fmt.Errorf("division by zero")
			}
			return l / r, nil
		case float64:
			if r == 0 {
				return nil, fmt.Errorf("division by zero")
			}
			return float64(l) / r, nil
		}
	case float64:
		switch r := right.(type) {
		case int64:
			if r == 0 {
				return nil, fmt.Errorf("division by zero")
			}
			return l / float64(r), nil
		case float64:
			if r == 0 {
				return nil, fmt.Errorf("division by zero")
			}
			return l / r, nil
		}
	}
	return nil, fmt.Errorf("cannot divide %T and %T", left, right)
}

func (vm *VM) mod(left, right interface{}) (interface{}, error) {
	l, lok := left.(int64)
	r, rok := right.(int64)
	if !lok || !rok {
		return nil, fmt.Errorf("modulo requires integers")
	}
	if r == 0 {
		return nil, fmt.Errorf("modulo by zero")
	}
	return l % r, nil
}

// Comparison operations

func (vm *VM) eq(left, right interface{}) bool {
	return left == right
}

func (vm *VM) lt(left, right interface{}) (bool, error) {
	switch l := left.(type) {
	case int64:
		switch r := right.(type) {
		case int64:
			return l < r, nil
		case float64:
			return float64(l) < r, nil
		}
	case float64:
		switch r := right.(type) {
		case int64:
			return l < float64(r), nil
		case float64:
			return l < r, nil
		}
	}
	return false, fmt.Errorf("cannot compare %T and %T", left, right)
}

func (vm *VM) le(left, right interface{}) (bool, error) {
	switch l := left.(type) {
	case int64:
		switch r := right.(type) {
		case int64:
			return l <= r, nil
		case float64:
			return float64(l) <= r, nil
		}
	case float64:
		switch r := right.(type) {
		case int64:
			return l <= float64(r), nil
		case float64:
			return l <= r, nil
		}
	}
	return false, fmt.Errorf("cannot compare %T and %T", left, right)
}

func (vm *VM) gt(left, right interface{}) (bool, error) {
	switch l := left.(type) {
	case int64:
		switch r := right.(type) {
		case int64:
			return l > r, nil
		case float64:
			return float64(l) > r, nil
		}
	case float64:
		switch r := right.(type) {
		case int64:
			return l > float64(r), nil
		case float64:
			return l > r, nil
		}
	}
	return false, fmt.Errorf("cannot compare %T and %T", left, right)
}

func (vm *VM) ge(left, right interface{}) (bool, error) {
	switch l := left.(type) {
	case int64:
		switch r := right.(type) {
		case int64:
			return l >= r, nil
		case float64:
			return float64(l) >= r, nil
		}
	case float64:
		switch r := right.(type) {
		case int64:
			return l >= float64(r), nil
		case float64:
			return l >= r, nil
		}
	}
	return false, fmt.Errorf("cannot compare %T and %T", left, right)
}

// Helper function to convert to bool
func (vm *VM) toBool(val interface{}) bool {
	switch v := val.(type) {
	case bool:
		return v
	case int64:
		return v != 0
	case float64:
		return v != 0
	case string:
		return v != ""
	case nil:
		return false
	default:
		return true
	}
}

