	case *ast.BinaryOp:
		left, err := b.buildExpr(e.Left)
		if err != nil {
			return Value{}, err
		}
		right, err := b.buildExpr(e.Right)
		if err != nil {
			return Value{}, err
		}

		opType := typeFromOp(e.Op)
		binOp := &Instruction{
			Type:   InstBinOp,
			OpType: opType,
			Ops:    []Value{left, right},
			Result: Value{
				ID:   b.nextValID,
				Type: "i64",
			},
		}
		b.currBlock.AddInstruction(binOp)
		b.nextValID++
		return binOp.Result, nil

	case *ast.UnaryOp:
		operand, err := b.buildExpr(e.Operand)
		if err != nil {
			return Value{}, err
		}

		opStr := e.OpToken.Lexeme
		unaryOp := &Instruction{
			Type:   InstUnaryOp,
			OpType: opStr,
			Ops:    []Value{operand},
			Result: Value{
				ID:   b.nextValID,
				Type: "i64",
			},
		}
		b.currBlock.AddInstruction(unaryOp)
		b.nextValID++
		return unaryOp.Result, nil

	case *ast.Call:
		args := []Value{}
		for _, arg := range e.Arguments {
			val, err := b.buildExpr(arg)
			if err != nil {
				return Value{}, err
			}
			args = append(args, val)
		}

		fnName := ""
		if id, ok := e.Function.(*ast.Identifier); ok {
			fnName = id.Name
		}

		callInst := &Instruction{
			Type:   InstCall,
			Meta:   fnName,
			Ops:    args,
			Result: Value{
				ID:   b.nextValID,
				Type: "i64",
			},
		}
		b.currBlock.AddInstruction(callInst)
		b.nextValID++
		return callInst.Result, nil

	default:
		return Value{}, fmt.Errorf("unsupported expression type: %T", expr)
	}
}

// buildLiteral builds a literal expression
func (b *Builder) buildLiteral(lit *ast.Literal) (Value, error) {
	litType := ""
	switch lit.Value.(type) {
	case int64:
		litType = "i64"
	case float64:
		litType = "f64"
	case bool:
		litType = "bool"
	case string:
		litType = "string"
	default:
		litType = "unknown"
	}

	inst := &Instruction{
		Type: InstLiteral,
		Meta: lit.Value,
		Result: Value{
			ID:   b.nextValID,
			Type: litType,
		},
	}
	b.currBlock.AddInstruction(inst)
	b.nextValID++
	return inst.Result, nil
}

// typeFromOp converts operator token type to IR op type
func typeFromOp(op lexer.TokenType) string {
	switch op {
	case lexer.PLUS:
		return "add"
	case lexer.MINUS:
		return "sub"
	case lexer.STAR:
		return "mul"
	case lexer.SLASH:
		return "div"
	case lexer.PERCENT:
		return "mod"
	case lexer.EQ_EQ:
		return "eq"
	case lexer.NOT_EQ:
		return "ne"
	case lexer.LT:
		return "lt"
	case lexer.LT_EQ:
		return "le"
	case lexer.GT:
		return "gt"
	case lexer.GT_EQ:
		return "ge"
	case lexer.AMP_AMP:
		return "and"
	case lexer.PIPE_PIPE:
		return "or"
	case lexer.AMP:
		return "bitand"
	case lexer.PIPE:
		return "bitor"
	case lexer.CARET:
		return "bitxor"
	default:
		return "unknown"
	}
}'.

